  img2 = loadImage("file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/murakami2.jpg");
  imageMode(CENTER);
  noStroke();
  background(255);
}

function draw() { 



  let i = 0;
  let _wG_1 = 0; while ((i <= 25) && ++_wG_1 < 20000) {
    drawPoint();
    i = i +1;
  }
}

function drawPoint() {


  let x = int(random(img.width));
  let y = int(random(img.height));
  let pix = img.get(x, y);

  let value = brightness(window.color(pix));
  var i = round( map (value, 0, 255, 0, 700*700-1) );
  let c2 = img2.pixels[i];


  fill(c2, 128);
  rect(x, y, random(0,15), random(0,15));
}
